<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { formatDateOnly } from '@/Support/dateOnly'; import { Head, Link, usePage } from '@inertiajs/vue3'; defineProps<{ schoolYear: any; calendar: any; upcomingEvents: any[] }>(); const page=usePage<any>(); const canAdvanced=page.props.auth.permissions.includes('advanced-academic.view');</script>
<template><Head title="Calendar" /><AuthenticatedLayout><div class="d-flex justify-content-between align-items-start mb-4"><div><h1 class="h2">Calendar</h1><p class="text-secondary mb-0">Your saved weekly schedule and calendar dates.</p></div><Link v-if="canAdvanced" class="btn btn-outline-secondary" :href="route('academic.calendars.index')">Advanced calendar setup</Link></div><div v-if="!schoolYear" class="card"><div class="empty-state">Choose an active school year to see calendar totals.</div></div><template v-else><div class="card mb-4"><div class="card-body"><h2 class="h4">{{ schoolYear.name }}</h2><p>{{ formatDateOnly(schoolYear.start_date) }} – {{ formatDateOnly(schoolYear.end_date) }}</p><p class="mb-0"><strong>Weekly instruction:</strong> {{ schoolYear.instructional_weekdays.length }} days per week</p></div></div><div v-if="calendar.state !== 'ready'" class="alert alert-warning">The selected calendar needs review before its exceptions can be applied.</div><div class="row g-3 mb-4"><div v-for="metric in [['Base days', calendar.summary.base_days], ['Removed days', calendar.summary.removed_days], ['Added days', calendar.summary.added_days], ['Scheduled days', calendar.summary.scheduled_days]]" :key="metric[0]" class="col-6 col-lg-3"><div class="card stat-card h-100"><div class="card-body"><span class="text-secondary">{{ metric[0] }}</span><strong class="display-6 d-block">{{ metric[1] }}</strong></div></div></div></div><div class="alert alert-info"><strong>Instructional-day target: {{ calendar.target ?? 'Not set' }}</strong><span v-if="calendar.target !== null && calendar.target !== calendar.summary.scheduled_days" class="d-block">This saved planning target differs from the calculated schedule. It has not been changed automatically.</span></div><div class="card"><div class="card-body"><h2 class="h4">Upcoming calendar dates</h2><p v-if="!upcomingEvents.length" class="text-secondary mb-0">No upcoming Calendar Events have been saved.</p><ul v-else class="list-group list-group-flush"><li v-for="event in upcomingEvents" :key="event.id" class="list-group-item px-0"><strong>{{ event.name }}</strong><span class="d-block">{{ formatDateOnly(event.event_date) }}<template v-if="event.end_date"> – {{ formatDateOnly(event.end_date) }}</template></span></li></ul></div></div></template></AuthenticatedLayout></template>
